2 + 1, xi.to(tl.float32))\n83:     tl.store(OUT + (row * (M + 1) + M + 0 * k) * 2, (ar - ai).to(tl.float32), mask=k == 0)\n84:     tl.store(OUT + (row * (M + 1) + M + 0 * k) * 2 + 1, 0.0, mask=k == 0)\n85: \n86: \n87: def validate_inputs(values, require_cuda=True):\n88:     \"\"\"Validate the public domain. Nonzero storage offsets are permitted.\"\"\"\n89:     def require(condition, message):\n90:         if not condition:\n91:             raise ValueError(message)\n92:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n93:     require(type(values) is torch.Tensor, \"ordinary torch.Tensor required\")\n94:     require(values.layout == torch.strided and values.is_contiguous(), \"contiguous strided input required\")\n95:     require(not values.requires_grad and not values.is_inference(), \"ordinary non-gradient input required\")\n96:     require(not values.is_neg() and not values.is_conj(), \"logical view flags are outside this domain\")\n97:     require(not require_cuda or values.is_cuda, \"CUDA input required by run\")\n98:     require(values.dtype == torch.float16, \"float16 input required\")\n99:     require(values.ndim == 2 and 1 <= values.shape[0] <= 256 and values.shape[1] in (64, 128, 256), \"shape must be [B,N], 1<=B<=256, N in {64,128,256}\")\n100:     require(bool(torch.isfinite(values).all()), \"all input values must be finite\")\n101:     return {\"valid\": True, \"batch\": values.shape[0], \"width\": values.shape[1]}\n102: \n103: \n104: def run(values):\n105:     \"\"\"Return real and imaginary components in a fresh FP32 tensor.\"\"\"\n106:     validate_inputs(values)\n107:     batch, n = values.shape\n108:     m = n // 2\n109:     with torch.cuda.device(values.device):\n110:         table = torch.tensor(_COSINE, dtype=torch.float64, device=values.device)\n111:         output = torch.empty((batch, m + 1, 2), dtype=torch.float32, device=values.device)\n112:         _realfft[(batch,)](values, table, output, N=n, M=m, L